"use client"

import React, { useState, useRef } from "react"
import { Send, Map } from "lucide-react"
import "./Ubicaciones.css"

export default function Ubicaciones() {
  const chatEndRef = useRef(null)
  const [messages, setMessages] = useState([
    { type: "bot", content: "Que edificio o salon te gustaria saber su ubicacion..." },
  ])
  const [inputValue, setInputValue] = useState("")
  const [showMap, setShowMap] = useState(false)

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" })
  }

  const handleSendMessage = () => {
    if (!inputValue.trim()) return
    const userMessage = { type: "user", content: inputValue }
    const botResponses = generateBotResponse(inputValue)
    setMessages(prev => [...prev, userMessage, ...botResponses])
    setInputValue("")
    setTimeout(scrollToBottom, 100)
  }

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage()
  }

  const generateBotResponse = (userInput) => {
    const input = userInput.toLowerCase()
    if (input.includes("edificio a")) {
      return [
        { type: "bot", content: "Sigue las siguientes indicaciones para llegar al Edificio A, además te muestro una foto del edificio." },
        { type: "bot", content: "map_only", mapImage: "/campus-map-with-route-to-building-a.jpg" },
        { type: "bot", content: "building_image", buildingImage: "/university-building-a-exterior-photo.jpg" },
        { type: "bot", content: "Si deseas conocer otra ubicación, escríbela en el chat. Para salir al menú principal, presiona 'Salir'.", actions: [{ label: "Salir", action: "exit" }] },
      ]
    }
    return [{ type: "bot", content: "Lo siento, no tengo información sobre esa ubicación. Intenta con otro edificio o salón." }]
  }

  const handleActionClick = (action) => {
    if (action === "exit") window.location.href = "/"
  }

  return (
    <div className="ubicaciones-container">
      <header className="ubicaciones-header">
        <h1 className="title">TalkinPon</h1>
        <h2 className="subtitle">Ubicaciones</h2>
        <div className="header-buttons">
          <button onClick={() => setShowMap(!showMap)} title={showMap ? "Ocultar mapa" : "Mostrar mapa"} className="icon-button">
            <Map className="icon" />
          </button>
          <img src="/university-logo-circular.jpg" alt="Logo" className="logo" />
        </div>
      </header>

      <div className="main-area">
        <div className={`chat-area ${showMap ? "half-width" : "full-width"}`}>
          <div className="messages-container">
            {messages.map((msg, idx) => (
              <div key={idx} className="message-wrapper">
                <div className={`message-row ${msg.type === "user" ? "justify-end" : "justify-start"}`}>
                  {msg.type === "bot" && <img src="/university-logo-circular.jpg" alt="Bot" className="avatar" />}
                  {msg.type === "user" && <img src="/university-logo-circular.jpg" alt="User" className="avatar" />}
                  <div className={`message-box ${msg.type} ${msg.content === "map_only" ? "map-only" : msg.content === "building_image" ? "building-image" : ""}`}>
                    {msg.content === "map_only" && <img src={msg.mapImage} alt="Mapa" className="map-image" />}
                    {msg.content === "building_image" && <img src={msg.buildingImage} alt="Edificio" className="building-img" />}
                    {msg.content !== "map_only" && msg.content !== "building_image" && <p>{msg.content}</p>}
                  </div>
                </div>
                {msg.actions && msg.actions.length > 0 && (
                  <div className="actions-row">
                    {msg.actions.map((actionBtn, aIdx) => (
                      <button key={aIdx} onClick={() => handleActionClick(actionBtn.action)} className="action-button">
                        {actionBtn.label}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            ))}
            <div ref={chatEndRef}></div>
          </div>

          <div className="input-area">
            <input
              type="text"
              placeholder="Pregunta lo que quieres..."
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyPress={handleKeyPress}
              className="chat-input"
            />
            <button onClick={handleSendMessage} className="send-button">
              <Send className="send-icon" />
            </button>
          </div>
        </div>

        {showMap && (
          <div className="map-area">
            <div className="map-header">
              <h3>Mapa del Campus</h3>
              <button onClick={() => setShowMap(false)} className="close-map">✕</button>
            </div>
            <div className="map-container">
              <img src="/interactive-campus-map-with-buildings-labeled.jpg" alt="Mapa del campus" className="map-full" />
            </div>
            <p className="map-note">Mapa interactivo del campus universitario</p>
          </div>
        )}
      </div>
    </div>
  )
}
